CREATE TABLE `md_item_budget_map` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `item_id` bigint DEFAULT NULL,
  `item_name` varchar(100) DEFAULT NULL,
  `budget_item_id` bigint DEFAULT NULL,
  `budget_dim_key` varchar(100) DEFAULT NULL,
  `control_type` varchar(20) DEFAULT NULL COMMENT '控制档位覆盖：HARD/SOFT/WARN/NONE；空=沿用方案级',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_item_budget` (`tenant_id`,`item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=214 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='费用类型-预算科目映射';
